    {capture $c_3}
      {=ui_text(ui_tpl('{0} · {1}', [ui_get($v_p, ['author']), ui_tpl(ui_get($v_labels, ['minutes']), [ui_get($v_p, ['minutes'])])]))}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_3])|noescape}
